        animId = requestAnimationFrame(render);
      } catch (err) {
        console.error('Render RAF error:', err);
      }
    }

    animId = requestAnimationFrame(render);

    return () => {
      if (typeof window !== 'undefined') {
        console.log('CLEANUP CALLED at frame:', (window as any).__aura_frames);
      }
      cancelAnimationFrame(animId);
